def transform(grid):
    """Fill the 6-mask using diagonal and central-axis symmetries."""
    n, m = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def orbit(r, c):
        pts = set()
        for a, b in ((r, c), (c, r)):
            for rr in (a, 31 - a):
                for cc in (b, 31 - b):
                    if 0 <= rr < n and 0 <= cc < m:
                        pts.add((rr, cc))
        return pts

    for r in range(n):
        for c in range(m):
            if grid[r][c] != 6:
                continue
            values = [grid[rr][cc] for rr, cc in orbit(r, c) if grid[rr][cc] != 6]
            if not values:
                raise ValueError(f"unrecoverable mask at {(r, c)}")
            if len(set(values)) != 1:
                raise ValueError(f"inconsistent symmetry at {(r, c)}: {values}")
            out[r][c] = values[0]
    return out
